import { traitToBadge } from '../app/jackpot-data.js';

// A compact receipt below the revealed board. Only the selected wallet's
// current/next-level spots are returned by the reader; never infer winners.
export function bafEntryGroups(entries = []) {
  const groups = new Map();
  for (const entry of entries) {
    const { level, sourceLevel, traitId } = entry;
    if (sourceLevel !== level && sourceLevel !== level + 1) continue;
    if (!Number.isInteger(traitId) || traitId < 0 || traitId > 255) continue;
    const count = Array.isArray(entry.spots) ? entry.spots.length : 0;
    if (!count) continue;
    const key = `${sourceLevel}:${traitId}`;
    if (!groups.has(key)) groups.set(key, { level, sourceLevel, traitId, count: 0 });
    groups.get(key).count += count;
  }
  return [...groups.values()].sort((a, b) => a.sourceLevel - b.sourceLevel || a.traitId - b.traitId);
}

export function createBafEntriesReceipt(host, fetchJSON) {
  let sequence = 0, activeKey = null;
  const reset = () => {
    sequence++; activeKey = null;
    if (host) { host.hidden = true; host.replaceChildren(); }
  };
  const reveal = async (day, player) => {
    if (!host || !Number.isInteger(day) || !/^0x[0-9a-f]{40}$/i.test(player || '')) return;
    const key = `${day}:${player.toLowerCase()}`;
    if (activeKey === key) return;
    reset(); activeKey = key;
    const seq = sequence;
    try {
      const data = await fetchJSON(`/player/${player.toLowerCase()}/baf-entries?day=${day}`);
      if (seq !== sequence) return;
      if (Number(data?.day) !== day || String(data?.player).toLowerCase() !== player.toLowerCase()) throw new Error('Mismatched BAF receipt');
      if (!data.supported || data.level == null) return;
      const groups = bafEntryGroups(data.entries);
      const title = document.createElement('h3'); title.textContent = 'YOUR BAF ENTRIES';
      host.appendChild(title);
      const list = document.createElement('div'); list.className = 'jackpot-baf-entries__list';
      for (const group of groups) {
        const row = document.createElement('div'); row.className = 'jackpot-baf-entries__group';
        const badge = traitToBadge(group.traitId, { mainJackpot: true });
        if (badge) {
          const img = document.createElement('img'); img.src = badge.path; img.alt = `Trait ${group.traitId}`;
          row.appendChild(img);
        }
        const label = document.createElement('span');
        label.textContent = `Level ${group.sourceLevel} · ${group.count} ${group.count === 1 ? 'entry' : 'entries'}`;
        row.appendChild(label); list.appendChild(row);
      }
      const note = document.createElement('p');
      note.textContent = groups.length ? 'Your sampled spots, including those that did not win.' : 'None of your entries were sampled from these traits.';
      host.append(list, note); host.hidden = false;
    } catch {
      if (seq !== sequence) return;
      host.replaceChildren();
      const retry = document.createElement('button'); retry.type = 'button';
      retry.textContent = 'BAF entries unavailable · Retry';
      retry.addEventListener('click', () => { activeKey = null; void reveal(day, player); });
      host.appendChild(retry); host.hidden = false;
    }
  };
  return { reset, reveal };
}
